package ru.skfu.softwarestore.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.Check; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="software_products") @Check(constraints="price > 0") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class SoftwareProduct { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=160) private String name; @Column(nullable=false,length=120) private String vendor; @Column(nullable=false,length=2000) private String description; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; @Builder.Default @Column(nullable=false,length=10) private String currency="RUB"; @Column(name="version_name",nullable=false,length=50) private String version; @Column(name="image_url",length=500) private String imageUrl; @Column(name="system_requirements",length=2000) private String systemRequirements; @Column(name="license_type",length=50) private String licenseType; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id",nullable=false) private Category category; @Enumerated(EnumType.STRING) @Builder.Default @Column(nullable=false,length=20) private ProductStatus status=ProductStatus.ACTIVE; @Builder.Default @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt=LocalDateTime.now(); @Builder.Default @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();} }
